package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class RatioContextStoriesTest {
 @Test public void allContextConditionsAreUniqueAndUsePublicBlankRelationships(){for(String id:List.of("proportion","el_proportional_split",RatioContextStories.ANGLE)){Set<String> seen=new HashSet<>();Set<Integer> groups=new HashSet<>();for(int i=0;i<RatioContextStories.domainSize(id);i++){Question q=RatioContextStories.at(id,i);assertTrue(seen.add(q.signature()));var v=RatioContextStories.read(q);assertNotNull(v);List<String> values,answers;if(id.equals("proportion")){Rational unit=Rational.of(v.c(),v.group()==0?v.a():v.b()),answer=unit.mul(Rational.of(v.group()==0?v.b():v.a()));values=List.of(""+v.a(),""+v.b(),""+v.c(),unit.toString(),answer.toString());answers=List.of(answer.toString());}else if(id.equals(RatioContextStories.ANGLE)){values=List.of("360",""+v.b(),Rational.of(v.b(),100).decimalText(),Rational.of(360*v.b(),100).decimalText());answers=List.of(values.get(3));}else{groups.add(v.group());assertNotEquals(v.b()*2,v.c());int unit=v.a()/v.c(),a=unit*v.b(),b=v.a()-a;assertEquals(0,v.a()%v.c());assertEquals(0,a%v.group());assertEquals(0,b%v.group());values=new ArrayList<>(List.of(""+v.a(),""+v.b(),""+v.c(),""+unit,""+a,""+b));if(v.group()>1)values.addAll(List.of(""+v.group(),""+(a/v.group()),""+(b/v.group())));answers=List.of(""+(a/v.group()),""+(b/v.group()));}assertTrue(new Checker().check(q,List.of(),answers).correct());q.answers=answers.stream().map(x->"99999").toArray(String[]::new);q.expression="poison";HelpPlan h=HelpPlan.forQuestion(q);assertEquals(values.size(),h.size());assertFalse(h.canTransfer());for(int j=0;j<values.size();j++){assertTrue(h.step(j).accepts(values.get(j)));assertFalse(h.step(j).accepts("99999"));} }if(id.equals("el_proportional_split"))assertEquals(12,groups.size());}}
 @Test public void selectedFreshSupplyAndAngleRemainExplicit(){var pack=GlobalCurriculum.packs("GB").stream().filter(x->x.id.equals("england-primary-2021-v1")).findFirst().orElseThrow();Generator g=new Generator(new Random(102));for(String id:List.of("proportion","el_proportional_split",RatioContextStories.ANGLE)){assertTrue(pack.inGrade(id,6));List<String> recent=new ArrayList<>();boolean story=false;int count=id.equals(RatioContextStories.ANGLE)?100:150;for(int i=0;i<count;i++){Question q=g.next(id,recent,false,GlobalCurriculum.limits(pack.id,id,6));assertFalse(recent.contains(q.signature()));recent.add(q.signature());story|=RatioContextStories.read(q)!=null;}assertTrue(story);}Learning.Profile profile=new Learning.Profile();profile.countryCode="KR";profile.educationSystem="kr-national";assertTrue(GlobalCurriculum.available(profile).stream().noneMatch(s->s.id.equals(RatioContextStories.ANGLE)));assertEquals("54",RatioContextStories.at(RatioContextStories.ANGLE,15).answers[0]);}
 @Test public void ordinaryRatioAndSplitDraftFormatsArePreserved(){Question ratio=RatioSplitSupply.at("proportion",0),split=RatioSplitSupply.at("el_proportional_split",0);assertEquals("ratio-value-relations-v1",ratio.studyGuide.teachingVersion);assertEquals("ratio-split-public-v1",split.studyGuide.teachingVersion);assertEquals(5,HelpPlan.forQuestion(ratio).size());assertEquals(7,HelpPlan.forQuestion(split).size());}
}
